import unittest
from candidate import count_distinct_characters

class TestCountDistinctCharacters(unittest.TestCase):
    def test_count_distinct_characters_normal_case(self):
        self.assertEqual(count_distinct_characters('xyzXYZ'), 3)

    def test_count_distinct_characters_name(self):
        self.assertEqual(count_distinct_characters('Jerry'), 4)

    def test_count_distinct_characters_empty_string(self):
        self.assertEqual(count_distinct_characters(''), 0)

    def test_count_distinct_characters_single_character(self):
        self.assertEqual(count_distinct_characters('a'), 1)

    def test_count_distinct_characters_uppercase(self):
        self.assertEqual(count_distinct_characters('ABC'), 3)

    def test_count_distinct_characters_lowercase(self):
        self.assertEqual(count_distinct_characters('abc'), 3)

    def test_count_distinct_characters_mixed_case(self):
        self.assertEqual(count_distinct_characters('AbC'), 3)

    def test_count_distinct_characters_numbers(self):
        self.assertEqual(count_distinct_characters('123'), 3)

    def test_count_distinct_characters_special_characters(self):
        self.assertEqual(count_distinct_characters('!@#'), 3)

    def test_count_distinct_characters_non_string_input(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(123)

    def test_count_distinct_characters_none_input(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(None)

if __name__ == '__main__':
    unittest.main()
